import math

def bell_number(n: int) -> int:
    """Return the nth Bell number."""
    if n < 0:
        raise ValueError("n must be non-negative")
    bell = [1]  # B0
    for i in range(1, n + 1):
        # B_i = sum_{k=0}^{i-1} C(i-1, k) * B_k
        total = 0
        for k in range(i):
            total += math.comb(i - 1, k) * bell[k]
        bell.append(total)
    return bell[n]

