def magic_square_test(matrix):
    # Check matrix is non-empty and square
    if not matrix or not all(isinstance(row, list) for row in matrix):
        return False
    n = len(matrix)
    if any(len(row) != n for row in matrix):
        return False
    # Compute target sum from first row
    target = sum(matrix[0])
    # Check rows
    for row in matrix:
        if sum(row) != target:
            return False
    # Check columns
    for col in range(n):
        if sum(matrix[row][col] for row in range(n)) != target:
            return False
    # Check main diagonal
    if sum(matrix[i][i] for i in range(n)) != target:
        return False
    # Check anti-diagonal
    if sum(matrix[i][n - 1 - i] for i in range(n)) != target:
        return False
    return True

