def get_total_number_of_sequences(m, n):
    if n == 1:
        return m
    dp_prev = [0] * (m + 1)
    for x in range(1, m + 1):
        dp_prev[x] = 1
    for _ in range(2, n + 1):
        prefix = [0] * (m + 1)
        s = 0
        for x in range(1, m + 1):
            s += dp_prev[x]
            prefix[x] = s
        dp_curr = [0] * (m + 1)
        for y in range(1, m + 1):
