def find_kth(A, B, k):
    # Ensure A is the shorter array for efficiency
    if len(A) > len(B):
        return find_kth(B, A, k)
    while True:
        if not A:
            return B[k - 1]
        if not B:
            return A[k - 1]
        if k == 1:
            return min(A[0], B[0])

        i = min(len(A), k // 2)
        j = k - i
        if j > len(B):
            i = k - len(B)
            j = len(B)

        if A[i - 1] < B[j - 1]:
            A = A[i:]
            k -= i
        else:
            B = B[j:]
            k -= j

# Test cases
