import math

def maxAverageOfPath(matrix):
    n = len(matrix)
    low = min(min(row) for row in matrix)
    high = max(max(row) for row in matrix)
    for _ in range(60):  # sufficient iterations for precision
        mid = (low + high) / 2.0
        dp = [[0.0] * n for _ in range(n)]
        dp[0][0] = matrix[0][0] - mid
        for i in range(1, n):
            dp[i][0] = dp[i-1][0] + matrix[i][0] - mid
        for j in range(1, n):
            dp[0][j] = dp[0][j-1] + matrix[0][j] - mid
        for i in range(1, n):
            for j in range(1, n):
                dp[i][j] = max(dp[i-1][j], dp[i][j-1]) + matrix[i][j] - mid
        if dp[n-1][n-1] >= 0:
            low = mid
        else:
            high = mid
    return round(low, 1)

